#!/usr/bin/env python3
"""Write the face directions into the firmware: ../../diskohedron/TileGeometry.h

    python3 export_geometry.py
"""
from pathlib import Path
from geometry import tile_geometry

OUT = Path(__file__).resolve().parents[2] / 'diskohedron' / 'TileGeometry.h'


def main():
    geo = tile_geometry()
    rows = [f'\t{{{c[0]: .6f}f, {c[1]: .6f}f, {c[2]: .6f}f}},  // tile {t}'
            for t in range(1, 31) for c in [geo[t][0]]]
    OUT.write_text('\n'.join([
        '// generated by tools/sphere/export_geometry.py - do not edit',
        '// unit vector from the centre of the lamp through the middle of each face,',
        '// tile 1 (first board in the chain) first; +z = top (rings of the old firmware)',
        '#pragma once',
        '',
        'static const float TILE_DIR[30][3] = {',
        *rows,
        '};',
        '',
    ]))
    print('wrote', OUT)


if __name__ == '__main__':
    main()
